func upsertEnv(env []string, key, value string) []string {
	prefix := key + "="
	entry := prefix + value
	result := make([]string, 0, len(env)+1)
	replaced := false
	for _, e := range env {
		if strings.HasPrefix(e, prefix) {
			if !replaced {
				result = append(result, entry)
				replaced = true
			}
			continue
		}

