func parsePostRewritePairs(r io.Reader) ([]rewritePair, error) {
	scanner := bufio.NewScanner(r)
	var pairs []rewritePair
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			return nil, fmt.Errorf("invalid post-rewrite mapping line: %q", line)
		}
		pairs = append(pairs, rewritePair{
			OldSHA: fields[0],
			NewSHA: fields[1],
		})
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan post-rewrite input: %w", err)
	}
	return pairs, nil
}

// hasUserContent checks if the message has any content besides comments and our trailer.
func hasUserContent(message string) bool {
	trailerPrefix := trailers.CheckpointTrailerKey + ":"
	for _, line := range strings.Split(message, "\n") {
		trimmed := strings.TrimSpace(line)
		// Skip empty lines
		if trimmed == "" {
			continue
		}
		// Skip comment lines
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		// Skip our trailer line
		if strings.HasPrefix(trimmed, trailerPrefix) {
			continue
		}
		// Found user content
		return true
	}
	return false
}

// stripCheckpointTrailer removes the Entire-Checkpoint trailer line from the message.
func stripCheckpointTrailer(message string) string {
	trailerPrefix := trailers.CheckpointTrailerKey + ":"
	var result []string
	for _, line := range strings.Split(message, "\n") {
		if !strings.HasPrefix(strings.TrimSpace(line), trailerPrefix) {
			result = append(result, line)
		}
	}
	return strings.Join(result, "\n")
}

func parseCheckpointFromCommitMessageFile(message string) (id.CheckpointID, bool) {
	lines := strings.Split(strings.TrimRight(message, "\n"), "\n")
	i := len(lines) - 1
	for i >= 0 {
		trimmed := strings.TrimSpace(lines[i])
		if trimmed != "" && !strings.HasPrefix(trimmed, "#") {
			break
		}
		i--
	}
	return trailers.ParseCheckpointFromFinalTrailerBlock(strings.Join(lines[:i+1], "\n"))
}

// isGitSequenceOperation checks if git is currently in the middle of a rebase,
// cherry-pick, or revert operation. During these operations, commits are being
// replayed and should not be linked to agent sessions.
//
// Detects:
//   - rebase: .git/rebase-merge/ or .git/rebase-apply/ directories
//   - cherry-pick: .git/CHERRY_PICK_HEAD file
//   - revert: .git/REVERT_HEAD file
func isGitSequenceOperation(ctx context.Context) bool {
	// Get git directory (handles worktrees and relative paths correctly)
	gitDir, err := GetGitDir(ctx)
	if err != nil {
		return false // Can't determine, assume not in sequence operation
	}

	// These markers live in the PER-WORKTREE git dir, not the common dir, which
	// is why this opens gitDir rather than using gitdir.Open.
	root, err := gitdir.OpenAt(gitDir)
	if err != nil {
		return false // Can't determine, assume not in sequence operation
	}

	// Check for rebase state directories, then cherry-pick and revert state files.
	for _, marker := range []string{"rebase-merge", "rebase-apply", "CHERRY_PICK_HEAD", "REVERT_HEAD"} {
		if _, err := root.Lstat(marker); err == nil {
			return true
		}
	}

	return false
}

// PrepareCommitMsg is called by the git prepare-commit-msg hook.
// Adds an Entire-Checkpoint trailer to the commit message with a stable checkpoint ID.
// Only adds a trailer if there's actually new session content to condense.
// The actual condensation happens in PostCommit - if the user removes the trailer,
// the commit will not be linked to the session (useful for "manual" commits).
// For amended commits, preserves the existing checkpoint ID.
	skipSources := []string{"merge", "squash", "commit"}
	for _, source := range skipSources {
		t.Run(source, func(t *testing.T) {
			if err := os.WriteFile(commitMsgFile, []byte(originalMsg), 0o644); err != nil {
				t.Fatalf("failed to write commit message file: %v", err)
			}

			prepErr := s.PrepareCommitMsg(context.Background(), commitMsgFile, source)
			if prepErr != nil {
				t.Errorf("PrepareCommitMsg() error = %v", prepErr)
			}

			// Message should be unchanged for these sources
			content, readErr := os.ReadFile(commitMsgFile)
			if readErr != nil {
				t.Fatalf("failed to read commit message file: %v", readErr)
			}
			if string(content) != originalMsg {
				t.Errorf("PrepareCommitMsg(source=%q) modified message: got %q, want %q",
					source, content, originalMsg)
			}
		})
	}
}

