package strategy

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

// migrateShadowBranchIfNeeded checks if HEAD has changed since the session started
// and either reconciles or migrates the shadow branch accordingly.
//
// Reconcile path: if HEAD carries this session's LastCheckpointID as an
// Entire-Checkpoint trailer (e.g. after git reset --hard to a condensed commit),
// both BaseCommit and AttributionBaseCommit are updated to HEAD. The old shadow
// branch is intentionally left untouched to preserve its checkpoint data.
//
// Migrate path: for all other HEAD changes (pull, rebase, tool-call commits),
// the shadow branch is renamed to the new base and only BaseCommit is updated.
// AttributionBaseCommit stays pinned for correct attribution.
//
// Returns (changed, reconciled, err):
//   - changed: true if either path fired, false for no-op
//   - reconciled: true only for the reconcile path; callers use this to know
//     that attribution must be recomputed against the new base since the old
//     base has been discarded (reconcile = reset-to-known-checkpoint)
func (s *ManualCommitStrategy) migrateShadowBranchIfNeeded(ctx context.Context, repo *git.Repository, state *SessionState) (bool, bool, error) {
	if state == nil || state.BaseCommit == "" {
		return false, false, nil
	}

	head, err := repo.Head()
	if err != nil {
		return false, false, fmt.Errorf("failed to get HEAD: %w", err)
	}

	currentHead := head.Hash().String()
	if state.BaseCommit == currentHead {
		return false, false, nil // No migration needed
	}

	// Reconcile path: if HEAD sits on the exact commit carrying this session's
	// LastCheckpointID, the user has reset back to the last condensed
	// checkpoint. Update both BaseCommit and AttributionBaseCommit to HEAD.
	// Deliberately do NOT rename or touch the old shadow branch — it
	// preserves checkpoint data from the discarded segment of history.
	//
	// The SHA guard (currentHead == LastCheckpointCommitHash) distinguishes a
	// true reset from a cherry-pick/rebase that merely preserved the trailer.
	// Cherry-picking a checkpoint commit creates a new SHA with the same
	// message; firing reconcile in that case would drop the pinned
	// AttributionBaseCommit and corrupt attribution for uncondensed work.
	// Legacy state files without LastCheckpointCommitHash fall back to
	// trailer-only matching for backward compatibility.
	if !state.LastCheckpointID.IsEmpty() {
		shaMismatch := state.LastCheckpointCommitHash != "" && state.LastCheckpointCommitHash != currentHead
		if shaMismatch {
			// Trailer may still be present via cherry-pick/rebase, but the
			// SHA doesn't match what we condensed into — fall through to migrate.
			logging.Debug(logging.WithComponent(ctx, "migration"), "reconcile skipped: HEAD SHA does not match LastCheckpointCommitHash",
				slog.String("head", currentHead[:7]),
				slog.String("expected", state.LastCheckpointCommitHash[:7]))
		} else {
			headCommit, commitErr := repo.CommitObject(head.Hash())
			if commitErr == nil {
				for _, cpID := range trailers.ParseAllCheckpoints(headCommit.Message) {
					if cpID.String() == state.LastCheckpointID.String() {
						state.BaseCommit = currentHead
						state.RealignAttributionBase(currentHead)
						logging.Info(logging.WithComponent(ctx, "migration"), "reconciled session to known checkpoint on HEAD",
							slog.String("checkpoint_id", state.LastCheckpointID.String()),
							slog.String("new_base", currentHead[:7]))
						return true, true, nil
					}
				}
			} else {
				logging.Warn(logging.WithComponent(ctx, "migration"), "could not load HEAD commit for reconcile check, falling through to migrate",
					slog.String("head", currentHead[:7]),
					slog.String("error", commitErr.Error()))
			}
		}
		// If SHA guard blocked, CommitObject failed, or no trailer matched,
		// fall through to the existing migrate path below.
	}

	changed, err := s.migrateShadowBranchToBaseCommit(ctx, repo, state, currentHead)
	return changed, false, err
}

// migrateShadowBranchToBaseCommit moves the current session's shadow branch to a
// new base commit-derived name and updates state.BaseCommit. It returns whether
// an existing shadow branch ref had to be migrated.
func (s *ManualCommitStrategy) migrateShadowBranchToBaseCommit(ctx context.Context, repo *git.Repository, state *SessionState, newBaseCommit string) (bool, error) {
	if state == nil || state.BaseCommit == "" || newBaseCommit == "" {
		return false, nil
	}
	if state.BaseCommit == newBaseCommit {
		return false, nil
	}

	// Base commit changed - check if old shadow branch exists and migrate it
	oldShadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	newShadowBranch := checkpoint.ShadowBranchNameForCommit(newBaseCommit, state.WorktreeID)

	// Guard against hash prefix collision: if both commits produce the same
	// shadow branch name (same 7-char prefix), just update state - no ref rename needed
	if oldShadowBranch == newShadowBranch {
		state.BaseCommit = newBaseCommit
		return true, nil
	}

	oldRefName := plumbing.NewBranchReferenceName(oldShadowBranch)
	oldRef, err := repo.Reference(oldRefName, true)
	if err != nil {
		// Old shadow branch doesn't exist - just update state.BaseCommit
		// This can happen if this is the first checkpoint after HEAD changed
		state.BaseCommit = newBaseCommit
		logging.Info(logging.WithComponent(ctx, "migration"), "updated session base commit",
			slog.String("new_base", newBaseCommit[:7]))
		return true, nil //nolint:nilerr // err is "reference not found" which is fine - just need to update state
	}

	// Old shadow branch exists - move it to new base commit
	newRefName := plumbing.NewBranchReferenceName(newShadowBranch)

	// Create new reference pointing to same commit as old shadow branch
	newRef := plumbing.NewHashReference(newRefName, oldRef.Hash())
	if err := repo.Storer.SetReference(newRef); err != nil {
		return false, fmt.Errorf("failed to create new shadow branch %s: %w", newShadowBranch, err)
	}

	// Delete old reference via CLI (go-git v5's RemoveReference doesn't persist with packed refs/worktrees)
	logCtx := logging.WithComponent(ctx, "migration")
	if err := DeleteBranchCLI(ctx, oldShadowBranch); err != nil {
		// Non-fatal: log but continue - the important thing is the new branch exists
		logging.Warn(logCtx, "failed to remove old shadow branch",
			slog.String("shadow_branch", oldShadowBranch),
			slog.String("error", err.Error()))
	}

	logging.Info(logCtx, "moved shadow branch (HEAD changed during session)",
		slog.String("from", oldShadowBranch),
		slog.String("to", newShadowBranch))

package strategy

import (
	"context"
	"testing"

	checkpointID "github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/testutil"

	"github.com/go-git/go-git/v6"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// setupMigrationRepo creates a temp repo with an initial commit and returns
// the directory and the initial HEAD hash. The caller must call t.Chdir(dir)
// before invoking migrateShadowBranchIfNeeded (it resolves CWD).
func setupMigrationRepo(t *testing.T) (string, string) {
	t.Helper()
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "init.txt", "init")
	testutil.GitAdd(t, dir, "init.txt")
	testutil.GitCommit(t, dir, "initial commit")
	return dir, testutil.GetHeadHash(t, dir)
}

// TestMigrateShadowBranch_ReconcilePath verifies that when HEAD carries the
// session's LastCheckpointID trailer, the reconcile path fires: both BaseCommit
// and AttributionBaseCommit are updated to HEAD, and the old shadow branch is
// left untouched.
func TestMigrateShadowBranch_ReconcilePath(t *testing.T) {
	dir, initHash := setupMigrationRepo(t)
	t.Chdir(dir)

	cpID := checkpointID.MustCheckpointID("abc123def456")

	// Create a commit with the matching Entire-Checkpoint trailer.
	testutil.WriteFile(t, dir, "file.txt", "content")
	testutil.GitAdd(t, dir, "file.txt")
	testutil.GitCommit(t, dir, "add feature\n\nEntire-Checkpoint: abc123def456")
	headHash := testutil.GetHeadHash(t, dir)

	// Set up a shadow branch at the OLD base to verify it is NOT deleted.
	oldShadowName := "entire/" + initHash[:7] + "-"
	testutil.CreateBranch(t, dir, oldShadowName)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	state := &SessionState{
		SessionID:             "test-session",
		BaseCommit:            initHash,
		AttributionBaseCommit: initHash,
		LastCheckpointID:      cpID,
	}

	s := &ManualCommitStrategy{}
	migrated, _, err := s.migrateShadowBranchIfNeeded(context.Background(), repo, state)
	require.NoError(t, err)

	assert.True(t, migrated, "reconcile path should report migrated=true")
	assert.Equal(t, headHash, state.BaseCommit, "BaseCommit should advance to HEAD")
	assert.Equal(t, headHash, state.AttributionBaseCommit, "AttributionBaseCommit should advance to HEAD")

	// Old shadow branch must still exist (not renamed or deleted).
	assert.True(t, testutil.BranchExists(t, dir, oldShadowName), "old shadow branch should be preserved")
}

// TestMigrateShadowBranch_CherryPickedCheckpointDoesNotTriggerReconcile
// verifies that a cherry-picked or rebased commit which *preserves* the
// session's LastCheckpointID trailer (same message, different SHA) does NOT
// fire the reconcile path. Only a reset back to the exact condensed commit
// should reconcile; cherry-pick creates a new SHA and must go through the
// migrate path so AttributionBaseCommit stays pinned.
func TestMigrateShadowBranch_CherryPickedCheckpointDoesNotTriggerReconcile(t *testing.T) {
	dir, initHash := setupMigrationRepo(t)
	t.Chdir(dir)

	cpID := checkpointID.MustCheckpointID("abc123def456")

	// HEAD carries the matching trailer but is a DIFFERENT SHA from the one
	// recorded at condensation time (LastCheckpointCommitHash). This is the
	// cherry-pick / rebase scenario.
	testutil.WriteFile(t, dir, "file.txt", "content")
	testutil.GitAdd(t, dir, "file.txt")
	testutil.GitCommit(t, dir, "cherry-picked commit\n\nEntire-Checkpoint: abc123def456")

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	state := &SessionState{
		SessionID:                "test-session-cherry-pick",
		BaseCommit:               initHash,
		AttributionBaseCommit:    "original-pinned-attribution",
		LastCheckpointID:         cpID,
		LastCheckpointCommitHash: "0000000000000000000000000000000000000042", // distinct from HEAD
	}

	s := &ManualCommitStrategy{}
	_, reconciled, err := s.migrateShadowBranchIfNeeded(context.Background(), repo, state)
	require.NoError(t, err)

	assert.False(t, reconciled,
		"cherry-pick preserving the trailer must NOT fire reconcile (HEAD SHA != LastCheckpointCommitHash); reconcile would drop the pinned AttributionBaseCommit and corrupt attribution math for uncondensed shadow-branch work")
	assert.Equal(t, "original-pinned-attribution", state.AttributionBaseCommit,
		"AttributionBaseCommit pin must survive a cherry-picked checkpoint trailer (migrate path preserves it; reconcile would not)")
}

// TestMigrateShadowBranch_ReconcileClearsDivergenceFlag verifies that the reconcile
// path also clears DivergenceNoticeShown. Without this, a session that warned about
// divergence, got reset back to a known checkpoint, and later diverged again would
// stay silent — defeating the show-once-per-divergence semantics.
func TestMigrateShadowBranch_ReconcileClearsDivergenceFlag(t *testing.T) {
	dir, initHash := setupMigrationRepo(t)
	t.Chdir(dir)

	cpID := checkpointID.MustCheckpointID("abc123def456")

	testutil.WriteFile(t, dir, "file.txt", "content")
	testutil.GitAdd(t, dir, "file.txt")
	testutil.GitCommit(t, dir, "add feature\n\nEntire-Checkpoint: abc123def456")

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	state := &SessionState{
		SessionID:             "test-session-reconcile-flag",
		BaseCommit:            initHash,
		AttributionBaseCommit: "some-older-commit",
		LastCheckpointID:      cpID,
		DivergenceNoticeShown: true, // was warned about divergence previously
	}

	s := &ManualCommitStrategy{}
	migrated, _, err := s.migrateShadowBranchIfNeeded(context.Background(), repo, state)
	require.NoError(t, err)
	require.True(t, migrated)

	assert.False(t, state.DivergenceNoticeShown,
		"reconcile must clear DivergenceNoticeShown so future divergence can warn again")
}

// TestMigrateShadowBranch_MigratePathPinsAttribution verifies the existing
// migrate path: when HEAD changes but has no matching trailer, BaseCommit
// advances but AttributionBaseCommit stays pinned.
func TestMigrateShadowBranch_MigratePathPinsAttribution(t *testing.T) {
	dir, initHash := setupMigrationRepo(t)
	t.Chdir(dir)

	cpID := checkpointID.MustCheckpointID("abc123def456")

	// Create a second commit WITHOUT any Entire-Checkpoint trailer.
	testutil.WriteFile(t, dir, "file.txt", "content")
	testutil.GitAdd(t, dir, "file.txt")
	testutil.GitCommit(t, dir, "add feature without trailer")
	headHash := testutil.GetHeadHash(t, dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	state := &SessionState{
		SessionID:             "test-session",
		BaseCommit:            initHash,
		AttributionBaseCommit: initHash,
		LastCheckpointID:      cpID,
	}

	s := &ManualCommitStrategy{}
	migrated, _, err := s.migrateShadowBranchIfNeeded(context.Background(), repo, state)
	require.NoError(t, err)

	assert.True(t, migrated, "migrate path should report migrated=true")
	assert.Equal(t, headHash, state.BaseCommit, "BaseCommit should advance to HEAD")
	assert.Equal(t, initHash, state.AttributionBaseCommit, "AttributionBaseCommit should stay pinned")
}

// TestMigrateShadowBranch_DifferentTrailerFromSameSession verifies that when
// HEAD has a DIFFERENT Entire-Checkpoint trailer (not matching LastCheckpointID),
// the migrate path fires instead of reconcile, and AttributionBaseCommit stays pinned.
func TestMigrateShadowBranch_DifferentTrailerFromSameSession(t *testing.T) {
	dir, initHash := setupMigrationRepo(t)
	t.Chdir(dir)

	sessionCpID := checkpointID.MustCheckpointID("abc123def456")

	// Create a commit with a DIFFERENT checkpoint ID.
	testutil.WriteFile(t, dir, "file.txt", "content")
	testutil.GitAdd(t, dir, "file.txt")
	testutil.GitCommit(t, dir, "add feature\n\nEntire-Checkpoint: 111111222222")
	headHash := testutil.GetHeadHash(t, dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	state := &SessionState{
		SessionID:             "test-session",
		BaseCommit:            initHash,
		AttributionBaseCommit: initHash,
		LastCheckpointID:      sessionCpID,
	}

	s := &ManualCommitStrategy{}
	migrated, _, err := s.migrateShadowBranchIfNeeded(context.Background(), repo, state)
	require.NoError(t, err)

	assert.True(t, migrated, "migrate path should fire")
	assert.Equal(t, headHash, state.BaseCommit, "BaseCommit should advance")
	assert.Equal(t, initHash, state.AttributionBaseCommit, "AttributionBaseCommit should stay pinned (migrate, not reconcile)")
}

// REDACTED verifies that when the session
// has never been condensed (LastCheckpointID is empty), the reconcile guard is
// skipped and the migrate path fires.
func REDACTED(t *testing.T) {
	dir, initHash := setupMigrationRepo(t)
	t.Chdir(dir)

	// Create a commit WITH a checkpoint trailer, but session has no LastCheckpointID.
	testutil.WriteFile(t, dir, "file.txt", "content")
	testutil.GitAdd(t, dir, "file.txt")
	testutil.GitCommit(t, dir, "add feature\n\nEntire-Checkpoint: abc123def456")
	headHash := testutil.GetHeadHash(t, dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	state := &SessionState{
		SessionID:             "test-session",
		BaseCommit:            initHash,
		AttributionBaseCommit: initHash,
		// LastCheckpointID is zero value (empty) - never condensed.
	}

	s := &ManualCommitStrategy{}
	migrated, _, err := s.migrateShadowBranchIfNeeded(context.Background(), repo, state)
	require.NoError(t, err)

	assert.True(t, migrated, "migrate path should fire")
	assert.Equal(t, headHash, state.BaseCommit, "BaseCommit should advance")
	assert.Equal(t, initHash, state.AttributionBaseCommit, "AttributionBaseCommit should stay pinned (migrate path)")
}

// TestMigrateShadowBranch_MultiTrailerHEAD verifies that the reconcile path
// matches when the session's LastCheckpointID appears as the SECOND trailer
// in a commit message (e.g. a squash-merge commit).
func TestMigrateShadowBranch_MultiTrailerHEAD(t *testing.T) {
	dir, initHash := setupMigrationRepo(t)
	t.Chdir(dir)

	cpID := checkpointID.MustCheckpointID("bbb222ccc333")

