func TestExplainCmd_CommitFlagWithGenerateValidates(t *testing.T) {
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "f.txt", "x")
	testutil.GitAdd(t, tmpDir, "f.txt")
