				CheckpointID: ulidID,
				SessionID:    "session-stray-ulid",
				Strategy:     "manual-commit",
				Transcript:   redact.AlreadyRedacted([]byte(`{"type":"user","message":{"content":[{"type":"text","text":"hello"}]}}` + "\n")),
