package strategy

import (
	"bytes"
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
	"github.com/entireio/cli/cmd/entire/cli/trailers"
	"github.com/entireio/cli/redact"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

const testNewActiveSessionID = "new-active-session"

// TestPostCommit_ActiveSession_CondensesImmediately verifies that PostCommit on
// an ACTIVE session condenses immediately and stays ACTIVE.
// With the 1:1 checkpoint model, each commit gets its own checkpoint right away.
func TestPostCommit_ActiveSession_CondensesImmediately(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}
	sessionID := "test-postcommit-active"

	// Initialize session and save a checkpoint so there is shadow branch content
	setupSessionWithCheckpoint(t, s, repo, dir, sessionID)

	// Set phase to ACTIVE (simulating agent mid-turn)
	state, err := s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	state.Phase = session.PhaseActive
	require.NoError(t, s.saveSessionState(context.Background(), state))

	// Create a commit WITH the Entire-Checkpoint trailer on the main branch
	commitWithCheckpointTrailer(t, repo, dir, "a1b2c3d4e5f6")

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// Verify phase stays ACTIVE (immediate condensation, no deferred phase)
	state, err = s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	require.NotNil(t, state)
	assert.Equal(t, session.PhaseActive, state.Phase,
		"ACTIVE session should stay ACTIVE after immediate condensation on GitCommit")

	// Verify condensation happened: the entire/checkpoints/v1 branch should exist
	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err, "entire/checkpoints/v1 branch should exist after immediate condensation")
	assert.NotNil(t, sessionsRef)

	// Verify StepCount was reset to 0 by condensation
	assert.Equal(t, 0, state.StepCount,
		"StepCount should be reset after immediate condensation")
}

// TestPostCommit_ReviewSession_PinnedToSingleCheckpoint verifies that a
// read-only review session is marked terminal once it has been condensed into a
// checkpoint, so PostCommit stops re-attaching it to every later commit in the
// worktree. This is the regression guard for the bug where a single `entire
// review` session leaked into many unrelated checkpoints' session lists (its
// prompt then rendering once per checkpoint on the session page). Contrast with
// TestPostCommit_ActiveSession_CondensesImmediately, where a normal ACTIVE
// session is expected to stay ACTIVE.
func TestPostCommit_ReviewSession_PinnedToSingleCheckpoint(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}
	sessionID := "test-postcommit-review"

	// Give the review session real shadow-branch content so its first PostCommit
	// actually condenses (handler.condensed == true).
	setupSessionWithCheckpoint(t, s, repo, dir, sessionID)

	// Tag it as an in-flight agent-review session.
	state, err := s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	now := time.Now()
	state.Phase = session.PhaseActive
	state.Kind = session.KindAgentReview
	state.LastInteractionTime = &now
	require.NoError(t, s.saveSessionState(context.Background(), state))

	// First commit: the review is condensed into this one checkpoint, then pinned.
	commitWithCheckpointTrailer(t, repo, dir, "a1b2c3d4e5f6")
	require.NoError(t, s.PostCommit(context.Background()))

	state, err = s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	require.NotNil(t, state)
	assert.Equal(t, session.PhaseEnded, state.Phase,
		"review session should be marked ENDED after its single condensation")
	assert.True(t, state.FullyCondensed,
		"review session should be FullyCondensed so PostCommit skips it on later commits")
	require.NotNil(t, state.EndedAt, "review session should have EndedAt stamped")
	firstCheckpoint := state.LastCheckpointID

	// Second commit (with a genuinely new file so it isn't an empty commit): the
	// pinned review session must NOT be re-condensed, i.e. it must not be
	// attached to a second checkpoint.
	require.NoError(t, os.WriteFile(filepath.Join(dir, "second.txt"), []byte("unrelated change"), 0o644))
	commitFilesWithTrailer(t, repo, dir, "b2c3d4e5f6a1", "second.txt")
	require.NoError(t, s.PostCommit(context.Background()))

	state, err = s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	require.NotNil(t, state)
	assert.Equal(t, session.PhaseEnded, state.Phase, "review session should stay terminal")
	assert.True(t, state.FullyCondensed, "review session should stay FullyCondensed")
	assert.Equal(t, firstCheckpoint, state.LastCheckpointID,
		"review session must not be condensed into a second checkpoint")
}

// TestPostCommit_IdleSession_Condenses verifies that PostCommit on an IDLE
// session condenses session data and cleans up the shadow branch.
func TestPostCommit_IdleSession_Condenses(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}
	sessionID := "test-postcommit-idle"

	// Initialize session and save a checkpoint so there is shadow branch content
	setupSessionWithCheckpoint(t, s, repo, dir, sessionID)

	// Set phase to IDLE (agent turn finished, waiting for user)
	state, err := s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	state.Phase = session.PhaseIdle
	state.LastInteractionTime = nil
	state.FilesTouched = []string{"test.txt"}
	require.NoError(t, s.saveSessionState(context.Background(), state))

	// Record shadow branch name before PostCommit
	shadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)

	// Create a commit WITH the Entire-Checkpoint trailer
	commitWithCheckpointTrailer(t, repo, dir, "b2c3d4e5f6a1")

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// Verify condensation happened: the entire/checkpoints/v1 branch should exist
	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err, "entire/checkpoints/v1 branch should exist after condensation")
	assert.NotNil(t, sessionsRef)

	// Verify shadow branch IS deleted after condensation
	refName := plumbing.NewBranchReferenceName(shadowBranch)
	_, err = repo.Reference(refName, true)
	assert.Error(t, err,
		"shadow branch should be deleted after condensation for IDLE session")
}

// TestPostCommit_RebaseDuringActive_SkipsTransition verifies that PostCommit
// is a no-op during rebase operations, leaving the session phase unchanged.
func TestPostCommit_RebaseDuringActive_SkipsTransition(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}
	s := &ManualCommitStrategy{}
	sessionID := "test-postcommit-rebase"

	// Initialize session and save a checkpoint
	setupSessionWithCheckpoint(t, s, repo, dir, sessionID)

	// Set phase to ACTIVE
	state, err := s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	state.Phase = session.PhaseActive
	require.NoError(t, s.saveSessionState(context.Background(), state))

	// Capture shadow branch name BEFORE any state changes
	shadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	originalStepCount := state.StepCount

	// Simulate rebase in progress by creating .git/rebase-merge/ directory
	gitDir := filepath.Join(dir, ".git")
	rebaseMergeDir := filepath.Join(gitDir, "rebase-merge")
	require.NoError(t, os.MkdirAll(rebaseMergeDir, 0o755))
	defer os.RemoveAll(rebaseMergeDir)

	// Create a commit WITH the checkpoint trailer
	commitWithCheckpointTrailer(t, repo, dir, "c3d4e5f6a1b2")

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// Verify phase stayed ACTIVE (no transition during rebase)
	state, err = s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	require.NotNil(t, state)
	assert.Equal(t, session.PhaseActive, state.Phase,
		"session should stay ACTIVE during rebase (no transition)")

	// Verify StepCount was NOT reset (no condensation happened)
	assert.Equal(t, originalStepCount, state.StepCount,
		"StepCount should be unchanged - no condensation during rebase")

	// Verify NO condensation happened (entire/checkpoints/v1 branch should not exist)
	_, err = repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.Error(t, err,
		"entire/checkpoints/v1 branch should NOT exist - no condensation during rebase")

	// Verify shadow branch still exists (not cleaned up during rebase)
	refName := plumbing.NewBranchReferenceName(shadowBranch)
	_, err = repo.Reference(refName, true)
	assert.NoError(t, err,
		"shadow branch should be preserved during rebase")
}

// TestPostCommit_ReadOnlyActiveSessionNotCondensed verifies that an ACTIVE session
// with no tracked files is NOT condensed when another session claims the committed
// files. This prevents read-only sessions (e.g., codex exec from summarize) from
// being condensed into checkpoints they didn't contribute to.
func TestPostCommit_ReadOnlyActiveSessionNotCondensed(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}
	idleSessionID := "test-postcommit-idle-multi"
	activeSessionID := "test-postcommit-active-multi"

	// Initialize the idle session with a checkpoint
	setupSessionWithCheckpoint(t, s, repo, dir, idleSessionID)

	// Get worktree path and base commit from the idle session
	idleState, err := s.loadSessionState(context.Background(), idleSessionID)
	require.NoError(t, err)
	worktreePath := idleState.WorktreePath
	baseCommit := idleState.BaseCommit
	worktreeID := idleState.WorktreeID

	// Set idle session to IDLE phase
	idleState.Phase = session.PhaseIdle
	idleState.LastInteractionTime = nil
	idleState.FilesTouched = []string{"test.txt"}
	require.NoError(t, s.saveSessionState(context.Background(), idleState))

	// Create a second session with the SAME base commit and worktree (concurrent session).
	// This session is ACTIVE but has NO checkpoints (StepCount=0, no shadow branch content)
	// and NO files touched. With multiple sessions present, the read-only gate prevents
	// this session from being condensed — it never modified files, so there's nothing
	// meaningful to attach to the checkpoint.
	now := time.Now()
	activeState := &SessionState{
		SessionID:           activeSessionID,
		BaseCommit:          baseCommit,
		WorktreePath:        worktreePath,
		WorktreeID:          worktreeID,
		StartedAt:           now,
		Phase:               session.PhaseActive,
		LastInteractionTime: &now,
		StepCount:           0,
	}
	require.NoError(t, s.saveSessionState(context.Background(), activeState))

	// Record shadow branch name before PostCommit
	shadowBranch := getShadowBranchNameForCommit(baseCommit, worktreeID)

	// Create a commit WITH the checkpoint trailer
	commitWithCheckpointTrailer(t, repo, dir, "d4e5f6a1b2c3")

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// Verify the ACTIVE session stays ACTIVE (immediate condensation model)
	activeState, err = s.loadSessionState(context.Background(), activeSessionID)
	require.NoError(t, err)
	assert.Equal(t, session.PhaseActive, activeState.Phase,
		"ACTIVE session should stay ACTIVE after GitCommit")

	// Only the IDLE session should be condensed (entire/checkpoints/v1 branch should exist)
	idleState, err = s.loadSessionState(context.Background(), idleSessionID)
	require.NoError(t, err)
	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err, "entire/checkpoints/v1 branch should exist after condensation")
	require.NotNil(t, sessionsRef)

	// Verify IDLE session's StepCount was reset by condensation
	assert.Equal(t, 0, idleState.StepCount,
		"IDLE session StepCount should be reset after condensation")

	// Shadow branch should be preserved because the ACTIVE session was NOT condensed
	// (it had no files touched, and totalSessionCount > 1 triggered the gate)
	refName := plumbing.NewBranchReferenceName(shadowBranch)
	_, err = repo.Reference(refName, true)
	assert.NoError(t, err,
		"shadow branch should be preserved — uncondensed ACTIVE session still references it")
}

// TestPostCommit_CondensationFailure_PreservesShadowBranch verifies that when
// condensation fails (corrupted shadow branch), BaseCommit is NOT updated.
func TestPostCommit_CondensationFailure_PreservesShadowBranch(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)
package strategy

import (
	"context"
	"errors"
	"log/slog"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/entiredir"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing/object"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// unclaimedTrailerLogMessage is the line logUnclaimedCheckpointTrailer emits.
// Asserting on the log is the only way to observe it: it deliberately has no
// return value and no state side effect, because its whole purpose is to be
// greppable in .entire/logs.
const unclaimedTrailerLogMessage = "no session condensed into the commit's checkpoint trailer"

// TestPostCommit_UnclaimedCheckpointTrailer covers the one shape the line is
// for and the three the caller excludes. The exclusions matter even at DEBUG:
// an amend and a cherry-pick both reach "no session condensed" while their
// checkpoint exists, so without them the line says nothing useful when someone
// greps for it.
func TestPostCommit_UnclaimedCheckpointTrailer(t *testing.T) {
	const trailerID = "f6a1b2c3d4e5"

	tests := []struct {
		name string
		// phase the session is in when the trailered commit lands.
		phase session.Phase
		// noNewContent pins the transcript baseline to what the shadow branch
		// already holds, so condensation finds nothing to do — the state that
		// leaves a stamped trailer unfilled.
		noNewContent bool
		// ownsTrailer presets LastCheckpointID to the committed trailer, which
		// is what an amend looks like: the trailer is inherited and the
		// checkpoint was written by the commit being amended.
		ownsTrailer bool
		// sequenceOp simulates rebase/cherry-pick/revert via .git/rebase-merge.
		sequenceOp bool
		// endedAndCondensed makes the loop skip this session entirely, so its
		// ownership is only visible from the pre-loop snapshot.
		endedAndCondensed bool
		// signalAlreadyReported makes newCommitCondensedSignal dedupe and return
		// nil for a condensation that still happens — the amend-re-condense
		// shape, and the reason claim cannot be read off the telemetry signal.
		signalAlreadyReported bool
		wantLogged            bool
	}{
		{
			name:         "idle session with nothing to condense is unclaimed",
			phase:        session.PhaseIdle,
			noNewContent: true,
			wantLogged:   true,
		},
		{
			name:         "amend is claimed: the session already owns the checkpoint",
			phase:        session.PhaseIdle,
			noNewContent: true,
			ownsTrailer:  true,
		},
		{
			name:              "amend after the session ended is claimed: the loop skips its owner",
			phase:             session.PhaseEnded,
			noNewContent:      true,
			ownsTrailer:       true,
			endedAndCondensed: true,
		},
		{
			name:         "sequence operation is excluded: ownership is not local",
			phase:        session.PhaseIdle,
			noNewContent: true,
			sequenceOp:   true,
		},
		{
			name:  "active session that condenses is claimed",
			phase: session.PhaseActive,
		},
		{
			name:                  "condensing with a deduped telemetry signal is still claimed",
			phase:                 session.PhaseActive,
			signalAlreadyReported: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dir := setupGitRepo(t)
			t.Chdir(dir)

			repo, err := OpenRepository(context.Background())
			require.NoError(t, err)

			s := &ManualCommitStrategy{}
			sessionID := "test-unclaimed-trailer"
			setupSessionWithCheckpoint(t, s, repo, dir, sessionID)

			state, err := s.loadSessionState(context.Background(), sessionID)
			require.NoError(t, err)
			state.Phase = tt.phase
			if tt.noNewContent {
				state.LastInteractionTime = nil
				state.CheckpointTranscriptStart = 2
				state.CheckpointTranscriptSize = shadowTranscriptSize(t, repo, state)
			}
			if tt.ownsTrailer {
				state.LastCheckpointID = id.MustCheckpointID(trailerID)
			}
			if tt.endedAndCondensed {
				state.FullyCondensed = true
			}
			if tt.signalAlreadyReported {
				state.CommitCondensedSignalCheckpointID = id.MustCheckpointID(trailerID).String()
			}
			require.NoError(t, s.saveSessionState(context.Background(), state))

			if tt.sequenceOp {
				require.NoError(t, os.MkdirAll(filepath.Join(dir, ".git", "rebase-merge"), 0o750))
			}

			commitWithCheckpointTrailer(t, repo, dir, trailerID)

			logs := captureStrategyLogs(t, func(ctx context.Context) {
				require.NoError(t, s.PostCommit(ctx))
			})

			if tt.wantLogged {
				assert.Contains(t, logs, unclaimedTrailerLogMessage,
					"expected the unclaimed-trailer line")
				assert.Contains(t, logs, `"level":"DEBUG"`,
					"DEBUG, not WARN: the condition has false-positive classes this cannot exclude")
				return
			}
			assert.NotContains(t, logs, unclaimedTrailerLogMessage,
				"the trailer resolves to a real checkpoint here; logging it would be a false positive")
		})
	}
}

// captureStrategyLogs runs fn with a real Logger writing to a temp directory and
// returns everything it emitted. A real Logger rather than a fake handler keeps
// the assertion honest about level, since that is half of what is under test.
func captureStrategyLogs(t *testing.T, fn func(ctx context.Context)) string {
	t.Helper()

	worktree := t.TempDir()
	logger, err := logging.New(logging.Config{
		Root:  entiredir.OpenerAt(worktree),
		Dir:   logging.LogsName,
		Level: slog.LevelDebug,
	})
	require.NoError(t, err)

	fn(logging.WithLogger(context.Background(), logger))
	require.NoError(t, logger.Close())

	content, err := os.ReadFile(filepath.Join(worktree, logging.LogsDir, logging.LogFileName))
	if errors.Is(err, os.ErrNotExist) {
		return ""
	}
	require.NoError(t, err)
	return string(content)
}

// TestPostCommit_PartialCommit_TrailerIsClaimed is the regression guard for inferring
// condensation from session state instead of reading it from
// postCommitProcessSessionLocked. A partial commit condenses successfully and
// then carries the uncommitted files forward, and carryForwardToNewShadowBranch
// clears LastCheckpointID on the way out — so the post-loop state of a
// successful condensation is identical to never having condensed.
// TestPostCommit_ActiveSession_CarryForward_PartialCommit pins that clearing as
// intended behaviour; this pins that the trailer is still counted as claimed.
func TestPostCommit_PartialCommit_TrailerIsClaimed(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := OpenRepository(context.Background())
	require.NoError(t, err)

	s := &ManualCommitStrategy{}
	sessionID := "test-unclaimed-partial-commit"

	metadataDir := ".entire/metadata/" + sessionID
	metadataDirAbs := filepath.Join(dir, metadataDir)
	require.NoError(t, os.MkdirAll(metadataDirAbs, 0o750))
	transcript := `{"type":"human","message":{"content":"create files A B C"}}
{"type":"assistant","message":{"content":"creating files"}}
`
	require.NoError(t, os.WriteFile(
		filepath.Join(metadataDirAbs, paths.TranscriptFileName), []byte(transcript), 0o600))

	for _, name := range []string{"A.txt", "B.txt", "C.txt"} {
		require.NoError(t, os.WriteFile(filepath.Join(dir, name), []byte(name), 0o600))
	}
	require.NoError(t, s.SaveStep(context.Background(), StepContext{
		SessionID:     sessionID,
		NewFiles:      []string{"A.txt", "B.txt", "C.txt"},
		MetadataDir:   metadataDir,
		CommitMessage: "Checkpoint: files A, B, C",
		AuthorName:    "Test",
		AuthorEmail:   "test@test.com",
	}))

	state, err := s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	state.Phase = session.PhaseActive
	require.NoError(t, s.saveSessionState(context.Background(), state))

	// Commit A and B but not C, so condensation succeeds and carry-forward runs.
	wt, err := repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("A.txt")
	require.NoError(t, err)
	_, err = wt.Add("B.txt")
	require.NoError(t, err)
	_, err = wt.Commit(
		"commit A and B\n\n"+trailers.CheckpointTrailerKey+": cf1cf2cf3cf4\n",
		&git.CommitOptions{Author: &object.Signature{
			Name: "Test", Email: "test@test.com", When: time.Now(),
		}})
	require.NoError(t, err)

	logs := captureStrategyLogs(t, func(ctx context.Context) {
		require.NoError(t, s.PostCommit(ctx))
	})

	state, err = s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	require.Equal(t, []string{"C.txt"}, state.FilesTouched,
		"precondition: carry-forward must have run, which is what clears LastCheckpointID")
	require.Empty(t, state.LastCheckpointID,
		"precondition: carry-forward cleared the ID the warning must not depend on")

	assert.NotContains(t, logs, unclaimedTrailerLogMessage,
		"a partial commit condensed successfully; the trailer resolves")
}

