	if err := json.Unmarshal(bTrue, &rawTrue); err != nil {
		t.Fatalf("unmarshal true: %v", err)
	}
	if got, ok := rawTrue["has_review"].(bool); !ok || !got {
		t.Errorf(`expected "has_review":true, got %v (raw: %s)`, rawTrue["has_review"], string(bTrue))
